    def _defence(self, state, acts):
        icpt = [a for a in acts if a.kind == 'intercept']
        if icpt:
            o = state.ctx.off[state.pending[0]]
            return min(icpt, key=lambda a: o.r['pass'] - state.ctx.dfn[a.piece].r['intercept'])
