        for a in acts:
            nxt = apply(state, a)
            v = expected(nxt, immediate_shot_value)
            if a.kind not in ('end_turn',):
                v += Fraction(1, 1000)        # spend tokens only for a real gain
            if best_v is None or v < best_v:
                best, best_v = a, v
